// Forgejo's push mirrors whose last two or more syncs failed, counted across runs; a sync without
// error resets the count. Each run posts them ending two hours on, so one alert lasts while they fail.
// a host without Forgejo's key has nothing to check
if (!$env.GIT_API_KEY) return [];
const helpers = this.helpers;
const PAGE = 50;
const forgejo = (path, qs) => helpers.httpRequest({
  url: 'http://127.0.0.1:3030/api/v1' + path, qs, json: true,
  headers: { Authorization: `token ${$env.GIT_API_KEY}` },
});
const repos = [];
for (let page = 1; ; page++) {
  const batch = await forgejo('/user/repos', { page, limit: PAGE });
  repos.push(...batch);
  if (batch.length < PAGE) break;
}

const state = $getWorkflowStaticData('global');
const counted = state.mirrors || {};
const mirrors = {};
const failing = [];
const startsAt = $now.toISO();
const endsAt = $now.plus({ hours: 2 }).toISO();
for (const repo of repos) {
  for (const mirror of await forgejo(`/repos/${repo.full_name}/push_mirrors`)) {
    const id = `${repo.full_name} ${mirror.remote_name}`;
    const before = counted[id] || { failures: 0, update: null };
    // a failed sync counts once, by its time
    const now = !mirror.last_error ? { failures: 0, update: null }
      : mirror.last_update === before.update ? before
      : { failures: before.failures + 1, update: mirror.last_update };
    mirrors[id] = now;
    if (now.failures < 2) continue;
    // ssh://git@host/… or git@host:… -> host
    const remote = mirror.remote_address.replace(/^\w+:\/\//, '').replace(/^[^@/]*@/, '').split(/[:/]/)[0];
    const error = mirror.last_error.trim().split('\n')[0].slice(0, 120);
    failing.push({ json: {
      mirror: mirror.remote_name,
      summary: `${repo.full_name} → ${remote}: ${error}`,
      link: `${repo.html_url}/settings`,
      startsAt,
      endsAt,
    } });
  }
}
state.mirrors = mirrors;
return failing;
